import bisect
from collections import defaultdict

class TweetCounts:
    def __init__(self):
        self.data = defaultdict(list)

    def recordTweet(self, tweetName: str, time: int) -> None:
        bisect.insort(self.data[tweetName], time)

    def getTweetCountsPerFrequency(self, freq: str, tweetName: str, startTime: int, endTime: int) -> List[int]:
        size = {"minute": 60, "hour": 3600, "day": 86400}[freq]
        res = [0] * ((endTime - startTime) // size + 1)
        times = self.data[tweetName]
        lo = bisect.bisect_left(times, startTime)
        hi = bisect.bisect_right(times, endTime)
        for i in range(lo, hi):
            res[(times[i] - startTime) // size] += 1
        return res

