        auto& v = data[tweetName];
        v.insert(upper_bound(v.begin(), v.end(), time), time);
    }

    vector<int> getTweetCountsPerFrequency(string freq, string tweetName, int startTime, int endTime) {
        int size = freq == "minute" ? 60 : freq == "hour" ? 3600 : 86400;
        vector<int>& v = data[tweetName];
        vector<int> res((endTime - startTime) / size + 1, 0);
        auto lo = lower_bound(v.begin(), v.end(), startTime);
        auto hi = upper_bound(v.begin(), v.end(), endTime);
        for (auto it = lo; it != hi; ++it)
            res[(*it - startTime) / size]++;
        return res;
    }
};

