class TweetCounts {
    private Map<String, List<Integer>> data = new HashMap<>();

    public TweetCounts() {}

    public void recordTweet(String tweetName, int time) {
        List<Integer> v = data.computeIfAbsent(tweetName, k -> new ArrayList<>());
        int pos = Collections.binarySearch(v, time);
        if (pos < 0) pos = -pos - 1;
        else pos++;
        v.add(pos, time);
    }

    public List<Integer> getTweetCountsPerFrequency(String freq, String tweetName, int startTime, int endTime) {
        int size = freq.equals("minute") ? 60 : freq.equals("hour") ? 3600 : 86400;
        List<Integer> v = data.getOrDefault(tweetName, Collections.emptyList());
        Integer[] res = new Integer[(endTime - startTime) / size + 1];
        Arrays.fill(res, 0);
        int lo = 0, hi = v.size();
        while (lo < hi) { int m = (lo + hi) >>> 1; if (v.get(m) < startTime) lo = m + 1; else hi = m; }
        int start = lo;
        lo = start; hi = v.size();
        while (lo < hi) { int m = (lo + hi) >>> 1; if (v.get(m) <= endTime) lo = m + 1; else hi = m; }
        for (int i = start; i < lo; i++)
            res[(v.get(i) - startTime) / size]++;
        return Arrays.asList(res);
    }
}

