var TweetCounts = function() {
    this.data = new Map();
};

TweetCounts.prototype.recordTweet = function(tweetName, time) {
    if (!this.data.has(tweetName)) this.data.set(tweetName, []);
    const v = this.data.get(tweetName);
    let lo = 0, hi = v.length;
    while (lo < hi) { const m = (lo + hi) >> 1; if (v[m] <= time) lo = m + 1; else hi = m; }
    v.splice(lo, 0, time);
};

TweetCounts.prototype.getTweetCountsPerFrequency = function(freq, tweetName, startTime, endTime) {
    const size = freq === "minute" ? 60 : freq === "hour" ? 3600 : 86400;
    const v = this.data.get(tweetName) || [];
    const res = new Array(Math.floor((endTime - startTime) / size) + 1).fill(0);
    let lo = 0, hi = v.length;
    while (lo < hi) { const m = (lo + hi) >> 1; if (v[m] < startTime) lo = m + 1; else hi = m; }
    let end = lo; lo = end; hi = v.length;
    while (lo < hi) { const m = (lo + hi) >> 1; if (v[m] <= endTime) lo = m + 1; else hi = m; }
    for (let i = end; i < lo; i++)
        res[Math.floor((v[i] - startTime) / size)]++;
    return res;
};
